python -c "import sqlite3; conn = sqlite3.connect('world.db'); cursor = conn.cursor(); tables = ['travel_users','travel_flights','travel_bookings','travel_expenses','users','flights','bookings','expenses']; 
for t in tables:
    try:
        cursor.execute(f'SELECT * FROM {t} LIMIT 2');
        print(f'{t}: {cursor.description}');
        print(cursor.fetchall());
        print()
    except Exception as e:
        print(f'{t}: {e}')
        print()" 2>&1

